const gld = $('Get GLD Metrics').first().json;
const sig = $('Get Signal Metrics').first().json;
const train = $('Get Training Status').first().json;

const trades = gld.trade_count || 0;
const pnl = ((gld.total_pnl_pct || 0) * 100).toFixed(3);
const wr = ((gld.win_rate || 0) * 100).toFixed(1);
const conf = ((gld.avg_confidence || 0) * 100).toFixed(1);

const sigTotal = sig.total_signals || 0;
const sigPassed = sig.passed_signals || 0;
const passRate = ((sig.pass_rate || 0) * 100).toFixed(1);
const collapse = sig.collapse_alert ? '⚠️ YES' : '✅ No';

const bars = train.bars_since_retrain || 0;
const modelAge = train.model_age_h != null ? train.model_age_h + 'h' : 'N/A';
const trainActive = train.training_active ? '🔁 RUNNING' : '💤 Idle';

const pnlNum = parseFloat(pnl);
const pnlEmoji = pnlNum > 0 ? '📈' : pnlNum < 0 ? '📉' : '➡️';
const date = new Date().toISOString().split('T')[0];

const goLivePct = Math.min(100, Math.round(trades / 200 * 100));

const msg = [
  pnlEmoji + ' **GoldenTrinity Daily Report — ' + date + '**',
  '',
  '**📊 Performance**',
  'P&L: ' + pnl + '% | Win Rate: ' + wr + '%',
  'Trades today: ' + trades + ' | Avg Confidence: ' + conf + '%',
  '',
  '**🔔 Signals**',
  'Generated: ' + sigTotal + ' | Passed Gate: ' + sigPassed + ' (' + passRate + '%)',
  'Confidence Collapse: ' + collapse,
  '',
  '**🧠 LSTM Training**',
  'Status: ' + trainActive + ' | Model Age: ' + modelAge,
  'New bars collected: ' + bars + ' / 50 needed',
  '',
  '**🎯 Go-Live Progress**',
  'Trades toward 200: ' + trades + ' (' + goLivePct + '% of today)',
  'Need: ≥200 trades | ≥50% win rate | Sharpe ≥1.0 | 30 days min',
].join('\n');

return [{ json: { message: msg, pnl: pnlNum, trades } }];
